function _lcEsc(s) {
  if (typeof escHTML === 'function') return escHTML(String(s));
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function _lcCfLines(cfIdx) {
  var row = CF_STEPS[cfIdx];
  if (!row || !row.lines) return [];
  return row.lines.slice();
}

